import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]

    def find(par, x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    ans = []
    for i in range(m):
        par = list(range(n + 1))
        for j in range(m):
            if j == i:
                continue
            a = find(par, edges[j][0])
            b = find(par, edges[j][1])
            if a != b:
                par[a] = b
        if find(par, edges[i][0]) != find(par, edges[i][1]):
            ans.append(i + 1)
    print(len(ans))
    if ans:
        print(" ".join(map(str, ans)))


main()
